    max_comb = 0
    for k in range(n // 2 + 1):
        max_comb = max(max_comb, combinations(n, k))
    print(f"n={n}: Max combinations = {max_comb}")

# For safety check
print(f"n=13: Max combinations = {combinations(13, 6)}")
